1.
public CImage InImage { get; set; } = new CImage(); // 直接初始化属性的时候，赋值。
2.
public CImage InImage { get; init; } = null!; // 定义一个不能为空的属性 InImage , 并且声明它必须在初始化的时候进行赋值, 如下
var convertParam = new ConvertParam()
{
InImage = new CImage ()
